contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool returned;

        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
        }

        assert(!reverted && returned == true);
    }

    receive() external payable {}
}

